INSERT INTO salary_history (employee_id, old_salary, new_salary)
SELECT id, salary, salary + 1000000 FROM employees WHERE dept = 'IT';

UPDATE employees SET salary = salary + 1000000 WHERE dept = 'IT';

SELECT e.name, e.salary, h.old_salary, h.new_salary
FROM employees e
LEFT JOIN salary_history h ON h.employee_id = e.id;
